static const float TRS64_b2[11] = { -7.13680124f, -4.52090359f, -0.93696934f,
                                    -1.86111081f, -1.75636232f, -2.31015062f,
                                    -2.54796171f, -3.99498248f, -6.91158438f,
                                    -2.03153944f, -1.64125967f };

static float TRS64_relu(float x)
{
    return x > 0.0f ? x : 0.0f;
}

static float TRS64_sigmoid(float x)
{
    if (x > 15.0f)
        return 1.0f;
    if (x < -15.0f)
        return 0.0f;
    return 1.0f / (1.0f + expf(-x));
}

int TRS_score_num64_operations_with_logits(
        const TRS_NumericFeaturesV2* f,
        float scores_out[TRS_SCORE_NUM64_N_OPERATIONS],
        float logits_out[TRS_SCORE_NUM64_N_OPERATIONS])
{
    float input[TRS64_N_FEATURES];
    float hidden[27];
    float output[TRS64_N_OUTPUTS];

    /* Extract and normalize features */
    input[0] = ((float)((
                        (((double)(long long)((
                                ((double)(f->count)) > 0.0
                                        ? log2((double)(f->count))
                                        : 0.0))))
                                        < ((double)(19))
                                ? (((double)(long long)((
                                          ((double)(f->count)) > 0.0
                                                  ? log2((double)(f->count))
                                                  : 0.0))))
                                : ((double)(19))))
                - TRS64_norm_mean[0])
            / TRS64_norm_std[0];
    input[1] =
            ((float)(f->zero_ratio) - TRS64_norm_mean[1]) / TRS64_norm_std[1];
    input[2] = ((float)((f->mean_abs_delta_u > 5000000000000000000ULL))
                - TRS64_norm_mean[2])
            / TRS64_norm_std[2];
    input[3] =
            ((float)((f->count > 42)) - TRS64_norm_mean[3]) / TRS64_norm_std[3];
    input[4] = ((float)(f->delta_up_ratio) - TRS64_norm_mean[4])
            / TRS64_norm_std[4];
    input[5] = ((float)(f->delta_down_ratio) - TRS64_norm_mean[5])
            / TRS64_norm_std[5];
    input[6] = ((float)((1.0 - f->delta_down_ratio)) - TRS64_norm_mean[6])
            / TRS64_norm_std[6];
    input[7]  = ((float)(f->range_u) - TRS64_norm_mean[7]) / TRS64_norm_std[7];
    input[8]  = ((float)(f->range_s) - TRS64_norm_mean[8]) / TRS64_norm_std[8];
    input[9]  = ((float)(f->min_u) - TRS64_norm_mean[9]) / TRS64_norm_std[9];
    input[10] = ((float)((f->min_u == 0)) - TRS64_norm_mean[10])
            / TRS64_norm_std[10];
    input[11] = ((float)(((f->min_u == 0) && (f->range_u > 4294967295ULL)))
                 - TRS64_norm_mean[11])
            / TRS64_norm_std[11];
    input[12] = ((float)((
                         (double)(f->cardinality_est)
                         / (((double)(f->count)) > ((double)(1))
                                    ? ((double)(f->count))
                                    : ((double)(1)))))
                 - TRS64_norm_mean[12])
            / TRS64_norm_std[12];
    input[13] = ((float)((
                         (double)(f->pair_cardinality_est)
                         / ((((double)(f->count) - (double)(1))) > ((double)(1))
                                    ? (((double)(f->count) - (double)(1)))
                                    : ((double)(1)))))
                 - TRS64_norm_mean[13])
            / TRS64_norm_std[13];
    input[14] = ((float)(f->sorted_gap_nmad) - TRS64_norm_mean[14])
            / TRS64_norm_std[14];
    input[15] = ((float)(f->sorted_gap_mode) - TRS64_norm_mean[15])
            / TRS64_norm_std[15];
    input[16] =
            ((float)(f->min_lb0) - TRS64_norm_mean[16]) / TRS64_norm_std[16];

    /* Layer 1 */
    for (int j = 0; j < 27; j++) {
        float sum = TRS64_b1[j];
        for (int i = 0; i < 17; i++) {
            sum += input[i] * TRS64_w1[i][j];
        }
        hidden[j] = TRS64_relu(sum);
    }

    /* Layer 2 */
    for (int j = 0; j < 11; j++) {
        float sum = TRS64_b2[j];
        for (int i = 0; i < 27; i++) {
            sum += hidden[i] * TRS64_w2[i][j];
        }
        if (logits_out)
            logits_out[j] = sum;
        output[j] = sum;
    }

    /* Copy scores and find best, by logit: saturated scores tie */
    int best = 0;
    for (int j = 0; j < TRS64_N_OUTPUTS; j++) {
        if (scores_out) {
            scores_out[j] = TRS64_sigmoid(output[j]);
        }
        if (output[j] > output[best])
            best = j;
    }

    return best;
}

int TRS_score_num64_operations(
        const TRS_NumericFeaturesV2* f,
        float scores_out[TRS_SCORE_NUM64_N_OPERATIONS])
{
    return TRS_score_num64_operations_with_logits(f, scores_out, NULL);
}

